<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { rolesApi, type PermissionRecord, type RoleRecord } from '../api/roles'
const rows=ref<RoleRecord[]>([]), permissions=ref<PermissionRecord[]>([]), selected=ref<RoleRecord|null>(null), mode=ref<'create'|'edit'|'permissions'|''>(''), busy=ref(false), loading=ref(false), error=ref(''), total=ref(0), pages=ref(1)
const q=reactive({page:1,size:10,keyword:'',status:''}), form=reactive({name:'',roleKey:'',status:'active' as 'active'|'inactive'}), ids=ref<string[]>([])
const explain=(e:unknown)=>e instanceof Error?e.message:'操作失败，请重试'
async function load(){loading.value=true;try{const r=await rolesApi.list(q);rows.value=r.list;total.value=r.total;pages.value=Math.max(1,r.pages)}catch(e){error.value=explain(e)}finally{loading.value=false}}
function close(){mode.value='';selected.value=null;ids.value=[]}
function create(){close();Object.assign(form,{name:'',roleKey:'',status:'active'});mode.value='create'}
async function open(row:RoleRecord,m:'edit'|'permissions'){busy.value=true;try{const r=await rolesApi.detail(row.id);selected.value=r;Object.assign(form,{name:r.name,roleKey:r.roleKey,status:r.status});ids.value=[...r.permissionIds];mode.value=m}catch(e){error.value=explain(e)}finally{busy.value=false}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{if(mode.value==='permissions'&&selected.value)await rolesApi.assignPermissions(selected.value.id,ids.value);else if(mode.value==='create')await rolesApi.create(form);else if(selected.value)await rolesApi.update(selected.value.id,form);close();await load()}catch(e){error.value=explain(e)}finally{busy.value=false}}
async function remove(row:RoleRecord){if(row.system||!confirm(`确认删除角色“${row.name}”？`))return;busy.value=true;try{await rolesApi.remove(row.id);await load()}catch(e){error.value=explain(e)}finally{busy.value=false}}
onMounted(async()=>{try{permissions.value=await rolesApi.permissions();await load()}catch(e){error.value=explain(e)}})
</script>
<template><div class="admin-page"><header class="page-heading"><div><span class="page-kicker">SECURITY</span><h1>角色权限</h1><p>维护角色、权限范围和员工授权边界。</p></div><button class="primary-button" :disabled="busy" @click="create">新增角色</button></header><p v-if="error" class="demo-banner" role="alert">{{error}}</p><section class="panel list-panel"><form class="role-tools" @submit.prevent="q.page=1;load()"><input v-model="q.keyword" placeholder="角色名称或标识"/><select v-model="q.status"><option value="">全部状态</option><option value="active">启用</option><option value="inactive">停用</option></select><button class="secondary-button" :disabled="busy">查询</button></form><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>角色</th><th>标识</th><th>权限数</th><th>员工数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.name}}{{r.system?'（内置）':''}}</td><td>{{r.roleKey}}</td><td>{{r.permissionIds.length}}</td><td>{{r.members}}</td><td>{{r.status==='active'?'启用':'停用'}}</td><td><button class="text-action" @click="open(r,'edit')">编辑</button><button class="text-action" @click="open(r,'permissions')">权限</button><button class="text-action danger" :disabled="r.system" @click="remove(r)">删除</button></td></tr><tr v-if="!rows.length"><td colspan="6" class="empty-state">{{loading?'正在加载…':'暂无角色'}}</td></tr></tbody></table></div><div class="pagination"><span>共 {{total}} 条</span><button :disabled="q.page<=1" @click="q.page--;load()">上一页</button><span>{{q.page}} / {{pages}}</span><button :disabled="q.page>=pages" @click="q.page++;load()">下一页</button></div></section><section v-if="mode" class="panel role-editor"><h2>{{mode==='create'?'新增角色':mode==='edit'?'编辑角色':'分配权限'}}</h2><form @submit.prevent="save"><template v-if="mode!=='permissions'"><label>角色名称<input v-model="form.name" required maxlength="100"/></label><label>角色标识<input v-model="form.roleKey" :disabled="mode==='edit'" required pattern="[a-z][a-z0-9_]{1,63}"/></label><label>状态<select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option></select></label></template><div v-else class="permission-grid"><label v-for="p in permissions" :key="p.id"><input v-model="ids" type="checkbox" :value="p.id"/> {{p.name}} <small>{{p.permissionKey}}</small></label></div><button class="primary-button" :disabled="busy">保存</button><button type="button" class="secondary-button" @click="close">取消</button></form></section></div></template>
<style scoped>.role-tools{display:flex;gap:12px;padding:20px;flex-wrap:wrap}.role-tools input,.role-tools select,.role-editor input,.role-editor select{padding:10px;border:1px solid #dce4de;border-radius:6px}.role-editor{padding:24px;margin-top:24px}.role-editor form{display:grid;gap:14px;max-width:720px}.role-editor label{display:grid;gap:6px}.permission-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.permission-grid label{display:block}.permission-grid input{margin-right:6px}.danger{color:#b94343}@media(max-width:700px){.permission-grid{grid-template-columns:1fr}}</style>
